<script setup>
import { onMounted, ref, computed, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, MapPin, Clock3, Users, Star, Bookmark, Check, CalendarDays, Package, CircleHelp, UserRound, Share2 } from 'lucide-vue-next'
import MapView from '../components/MapView.vue'
import { authRequest, state, money, dateText, niceTime, notify, toggleFavorite } from '../lib/state'
const route=useRoute(),router=useRouter(),item=ref(null),reviews=ref([]),seats=ref(1),saving=ref(false),booking=ref(false),saved=ref(false),confirmed=ref(null),stars=ref(5),comment=ref(''),reviewBusy=ref(false)
const isClient=computed(()=>state.user?.role==='client'),hasBooking=ref(false),mine=computed(()=>reviews.value.find(r=>r.userId===state.user?.id))
// Rama de Santiago: si se configura VITE_GOOGLE_MAPS_EMBED_KEY (Maps Embed API, uso gratuito) se muestra
// el mapa de Google; si no, se usa el mapa Leaflet + OpenStreetMap, que no necesita clave.
const googleKey=import.meta.env.VITE_GOOGLE_MAPS_EMBED_KEY||''
const googleMapUrl=computed(()=>googleKey&&item.value?`https://www.google.com/maps/embed/v1/place?${new URLSearchParams({key:googleKey,q:`${item.value.lat},${item.value.lon}`,zoom:'17'})}`:'')
const mapMarkers=computed(()=>item.value?[item.value]:[]),mapCenter=computed(()=>item.value?[item.value.lat,item.value.lon]:undefined)
async function load(){try{const [w,r,b]=await Promise.all([authRequest(`/workshops/${route.params.id}`),authRequest(`/workshops/${route.params.id}/reviews`),isClient.value?authRequest('/me/bookings'):Promise.resolve({items:[]})]);item.value=w.item;reviews.value=r.items;saved.value=state.favoriteIds.includes(w.item.id);hasBooking.value=b.items.some(x=>x.workshopId===w.item.id&&x.status==='confirmada');if(mine.value){stars.value=mine.value.stars;comment.value=mine.value.comment}}catch(e){notify(e.message)}}
onMounted(load)
async function toggleSave(){try{saving.value=true;saved.value=await toggleFavorite(item.value.id);notify(saved.value?'Guardado correctamente':'Quitado de Guardados')}catch(e){notify(e.message)}finally{saving.value=false}}
async function reserve(){try{booking.value=true;const r=await authRequest(`/workshops/${item.value.id}/bookings`,{method:'POST',body:{seats:Number(seats.value)}});confirmed.value=r.item;item.value=r.workshop;hasBooking.value=true;notify('¡Reserva confirmada!')}catch(e){notify(e.message)}finally{booking.value=false}}
async function sendReview(){try{reviewBusy.value=true;await authRequest(`/workshops/${item.value.id}/reviews`,{method:'POST',body:{stars:Number(stars.value),comment:comment.value}});const editingReview=!!mine.value;reviews.value=(await authRequest(`/workshops/${item.value.id}/reviews`)).items;item.value=(await authRequest(`/workshops/${item.value.id}`)).item;notify(editingReview?'Reseña actualizada':'¡Gracias por tu valoración!')}catch(e){notify(e.message)}finally{reviewBusy.value=false}}
function share(){navigator.clipboard?.writeText(window.location.href).then(()=>notify('Enlace copiado')).catch(()=>notify('Copia la dirección del navegador para compartir.'))}
</script>
<template>
  <div class="page detail-page"><button class="back-link" @click="router.back()"><ArrowLeft :size="18"/> Volver</button>
    <div v-if="!item" class="loading-area">Cargando detalle del taller...</div>
    <template v-else>
      <div class="detail-layout"><div class="detail-main"><img class="detail-hero-img" :src="item.image" :alt="item.title"/><div class="detail-title-row"><div><span class="eyebrow earth">{{item.category}} · {{item.level}}</span><h1>{{item.title}}</h1><div class="inline-meta"><span><MapPin :size="17"/> {{item.district}}, Lima</span><span><Star :size="17" fill="currentColor"/> {{item.rating??'Nuevo'}} ({{item.reviewCount}} reseñas)</span></div></div><div class="detail-actions"><button v-if="isClient" class="icon-pill" :disabled="saving" @click="toggleSave"><Bookmark :size="20" :fill="saved?'currentColor':'none'"/>{{saved?'Guardado':'Guardar'}}</button><button class="icon-pill" @click="share"><Share2 :size="18"/> Compartir</button></div></div>
        <div v-if="item.available===0" class="card-note warn">Este taller no tiene más cupos disponibles. Por eso no aparece en las búsquedas generales.</div><div v-else-if="item.enrollmentOpen===false" class="card-note warn">El tallerista cerró temporalmente las inscripciones. Guárdalo para revisar cuando vuelva a abrir cupos.</div>
        <section class="text-section"><h2>¿De qué trata este taller?</h2><p>{{item.summary}}</p><p>{{item.description}}</p></section>
        <div class="detail-feature-grid"><div class="feature-box"><CalendarDays :size="25"/><b>Horario</b><span>{{dateText(item.date)}}<br/>{{niceTime(item.startsAt)}} – {{niceTime(item.endsAt)}}</span></div><div class="feature-box"><MapPin :size="25"/><b>Local y ubicación</b><span>{{item.venue}}<br/>{{item.address}}</span></div><div class="feature-box"><Package :size="25"/><b>Materiales incluidos</b><span>{{item.materialsIncluded}}</span></div><div class="feature-box"><CircleHelp :size="25"/><b>¿Qué debes llevar?</b><span>{{item.materialsBring}}</span></div></div>
        <div v-if="item.instructorClaimed===false" class="card-note small">Ficha informativa creada por Hobbiz a partir de información pública; el taller aún no la administra.</div><div v-if="item.sampleData" class="card-note small">Precio, fecha y cupos de esta ficha son datos de ejemplo del prototipo; confírmalos con el taller.</div>
        <section class="text-section"><h2>Ubicación</h2><p class="muted">{{item.venue}} · {{item.address}}<template v-if="item.locationPrecision==='distrito'"> · <b>ubicación aproximada dentro de {{item.district}}</b></template></p><iframe v-if="googleMapUrl" :src="googleMapUrl" title="Mapa de ubicación del taller" width="100%" height="300" style="border:0;border-radius:18px" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><MapView v-else :markers="mapMarkers" :center="mapCenter" :zoom="16" height="280px"/><a class="text-link" :href="`https://www.openstreetmap.org/?mlat=${item.lat}&mlon=${item.lon}#map=18/${item.lat}/${item.lon}`" target="_blank" rel="noopener noreferrer">Abrir en OpenStreetMap ↗</a> · <a class="text-link" :href="`https://www.google.com/maps/dir/?api=1&destination=${item.lat},${item.lon}`" target="_blank" rel="noopener noreferrer">Cómo llegar (Google Maps) ↗</a></section>
        <section class="text-section" :style="{borderLeft: `5px solid ${item.instructorStudio?.accentColor||({terracota:'#c65c38',oliva:'#76905e',azul:'#648eaf',ciruela:'#7d4b6a',noche:'#2f3e5c'})[item.instructorStudio?.accent]||'#c65c38'}`,paddingLeft:'15px'}"><h2>Conoce al tallerista</h2><div class="instructor-summary"><img v-if="item.instructorStudio?.coverImage" :src="item.instructorStudio.coverImage" alt="Portada del estudio" width="96" height="80" style="border-radius:12px;object-fit:cover"/><span class="avatar">{{item.instructorName[0]}}</span><div><b>{{item.instructorName}}</b><p class="muted">{{item.instructorStudio?.bio || "Organiza esta experiencia para grupos pequeños en Lima."}}</p><RouterLink :to="`/estudio/${item.instructorId}`" class="text-link">Ver perfil del tallerista →</RouterLink><template v-for="(url,k) in item.instructorStudio?.links||{}" :key="k"> · <a :href="url" target="_blank" rel="noopener noreferrer" class="text-link">{{({web:'Sitio web',instagram:'Instagram',facebook:'Facebook',tiktok:'TikTok',whatsapp:'WhatsApp'})[k]}} ↗</a></template></div></div></section>
        <section class="text-section"><h2>Reseñas de participantes</h2><p class="muted">{{item.reviewCount}} opiniones · Valoración promedio {{item.rating??'pendiente'}}</p><div v-if="!reviews.length" class="card-note">Este taller todavía no tiene reseñas.</div><article v-for="r in reviews" :key="r.id" class="review-card"><div><b>{{r.name}}</b><span class="rating-review">{{'★'.repeat(r.stars)}}{{'☆'.repeat(5-r.stars)}}</span></div><p>{{r.comment}}</p></article>
          <div v-if="isClient && !hasBooking" class="card-note small">Podrás dejar tu reseña y calificación después de reservar este taller.</div><form v-if="isClient && hasBooking" class="review-form" @submit.prevent="sendReview"><h3>{{mine?'Editar tu reseña':'Dejar una reseña'}}</h3><p class="muted small">Tu reseña y calificación serán públicas para todos los usuarios.</p><div class="rating-input"><button v-for="s in 5" :key="s" type="button" :aria-label="`${s} estrellas`" @click="stars=s" :class="{'picked':s<=stars}">★</button></div><textarea v-model="comment" rows="3" minlength="8" maxlength="500" placeholder="Cuéntanos cómo fue tu experiencia..." required/><button class="btn light" type="submit" :disabled="reviewBusy">{{mine?'Guardar cambios':'Enviar valoración'}}</button></form>
        </section>
      </div>
      <aside class="booking-box"><div class="booking-price">{{money(item.price)}} <small>por persona</small></div><div class="booking-summary"><p><CalendarDays :size="18"/> {{dateText(item.date)}}</p><p><Clock3 :size="18"/> {{niceTime(item.startsAt)}} – {{niceTime(item.endsAt)}}</p><p><Users :size="18"/> {{item.available}} de {{item.capacity}} cupos disponibles</p><p><MapPin :size="18"/> {{item.venue}}, {{item.district}}</p></div>
        <template v-if="!isClient"><p class="card-note small">Vista de tallerista: las reservas se hacen desde una cuenta de cliente.</p></template><template v-else-if="confirmed"><div class="confirmation"><Check :size="30"/><strong>¡Reserva confirmada!</strong><p>Código {{confirmed.id.slice(0,8).toUpperCase()}} · {{confirmed.seats}} cupo(s)</p><p>Se agregó a tu perfil.</p></div><RouterLink to="/perfil" class="btn primary full">Ver mis reservas</RouterLink></template>
        <template v-else><label class="field">Cantidad de cupos<select v-model.number="seats" :disabled="item.available===0||item.enrollmentOpen===false"><option v-for="n in Math.min(5,item.available)" :key="n" :value="n">{{n}} {{n===1?'persona':'personas'}}</option></select></label><div class="booking-total"><span>Total estimado</span><b>{{money(item.price*seats)}}</b></div><button class="btn primary full" :disabled="booking || item.available===0 || item.enrollmentOpen===false || item.past" @click="reserve">{{item.past?'Taller ya realizado':item.available===0?'No hay más cupos disponibles':item.enrollmentOpen===false?'Inscripciones cerradas':booking?'Confirmando...':'Reservar taller'}}</button><p class="muted small center">Reserva simulada · No se procesan pagos reales.</p></template>
      </aside></div>
    </template>
  </div>
</template>
